  "implementation": "def solve(case):
    nodes = case['nodes']
    required_symbols = set(case['required_symbols'])
    node_map = {n['id']: n for n in nodes}
    children = {n['id']: [] for n in nodes}
    for n in nodes:
        p = n['parent']
        if p is not None:
            children[p].append(n['id'])
    # initial retained set and symbol counts
    retained = set(node_map.keys())
    symbol_count = {}
    for n in nodes:
        s = n['symbol']
        symbol_count[s] = symbol_count.get(s, 0) + 1
    # candidates: removable nodes, sorted by depth descending, then id ascending
    candidates = [n for n in nodes if n['removable']]
    candidates.sort(key=lambda x: (-x['depth'], x['id']))
    removed = []
    for c in candidates:
        nid = c['id']
        if nid not in retained:
            continue
        if c['symbol'] in required_symbols:
            continue
        # check children: none retained
        child_ids = children.get(nid, [])
        if any(cid in retained for cid in child_ids):
            continue
        # check required symbols after removal
        sym = c['symbol']
        if sym in required_symbols and symbol_count.get(sym, 0) <= 1:
            continue
        # remove
        removed.append(nid)
        retained.remove(nid)
        symbol_count[sym] -= 1
    retained_sorted = sorted(retained)
    return {
        'removed_node_ids': removed,
        'retained_node_ids': retained_sorted
    }"
}
